  const upgrade=appendText(root,'button','Enable / restore large-run defaults','secondary');upgrade.disabled=state.running||!state.recipe;upgrade.onclick=async()=>{try{await api('large-run',{});editingRecipe=false;await refresh();message('Large-run defaults saved. Spending budget and source boundaries are unchanged.');}catch(e){message(e.message,true);}};
