function explanatoryQuote(record){const raw=record.source_support_quote??record.source_supported_definition;const text=typeof raw==='string'?raw:raw&&typeof raw==='object'?raw.text:null;const reason=raw&&typeof raw==='object'&&typeof raw.reason==='string'?raw.reason:null;return {text:typeof text==='string'&&text.trim()?text:null,reason:reason||'no_exact_definition_quote'};}
function stopReasonText(reason){const names={spending_budget_reservation_exhausted:'The spending budget cannot cover another request reserve. Unfinished jobs remain pending.',request_budget_exhausted:'The maximum request count was reached. Unfinished jobs remain pending.',run_deadline_exhausted:'The run time limit was reached. Remaining work is saved.',cancelled_by_researcher:'You cancelled collection. Remaining work is saved for resume.',keyboard_interrupt:'Collection was interrupted. Review job state before resuming.',process_interrupted:'The process stopped before collection completed. Review saved jobs and uncertain outcomes.',interrupted_at_job_limit:'This invocation reached its job limit. Resume to process remaining work.',unresolved_uncertain_api_outcome:'A provider outcome is uncertain. Resolve it before another request; its cost reserve remains.'};return reason?(names[reason]||humanPath(reason)):null;}
function progressSummary(status,running=false,configured=false){const jobs=status.jobs||{},costs=Object.values(status.costs||{});const sum=key=>costs.length&&costs.every(row=>Number.isFinite(row[key]))?costs.reduce((total,row)=>total+row[key],0):null;const labels={ready:configured?'Ready to collect':'Set up your study',running:'Collecting',complete:'Collection completed',partial:'Partial coverage',cancelled:'Cancelled'};return {title:running?'Collecting':labels[status.status]||humanPath(status.status||'ready'),sources:status.counts?.sources,records:status.counts?.records??status.counts?.terms,evidence:status.counts?.occurrences,jobs:{done:jobs.done||0,running:jobs.running||0,pending:jobs.pending||0,partial:jobs.partial||0,failed:jobs.failed||0,uncertain:jobs.uncertain||0,split:jobs.split||0},provider_cost:sum('estimated_actual_usd'),simulated_cost:sum('simulated_usd'),pending_reserves:sum('pending_reservations_usd'),unknown_reserves:sum('reserved_unknown_usd'),failures:Array.isArray(status.failures)?status.failures.length:0,stop:stopReasonText(status.stop_reason),coverage:status.coverage,mode:status.mode,profile:status.profile};}
