  const revision=show([term.review_status,latest,state.recipe?.output?.attributes]);
  // Changing terms must not carry human text to a different record. Polling the
  // same term preserves edits, while saved/undone annotations update clean forms.
  if(annotationTerm!==selected||(!editingAnnotation&&annotationRevision!==revision)) {
    $('review-note').value=latest?.note||'';
    $('review-attributes').value=show(latest?.attributes||{});
    $('review-status').value=term.review_status||'unreviewed';
    editingAnnotation=false;editingRawAttributes=false;
    renderAttributeFields(latest?.attributes||{});
    if(annotationTerm!==selected){$('relation-other').value='';$('relation-search').value='';renderRelationChoices(records());}
  }
  annotationTerm=selected;annotationRevision=revision;
