function readHumanAttributes(){const value=JSON.parse($('review-attributes').value);if(!value||Array.isArray(value)||typeof value!=='object')throw new Error('Human attributes must be an object.');if(editingRawAttributes)return value;for(const [name,{input,type,initialValue}]of attributeControls){const raw=input.value;if(input.readOnly||raw===initialValue)continue;if(raw===''){delete value[name];continue;}if(type==='boolean')value[name]=raw==='true';else if(type==='array')value[name]=raw.split('\n').map(text=>text.trim()).filter(Boolean);else if(type==='number'||type==='integer'){const numeric=Number(raw);if(!Number.isFinite(numeric)||type==='integer'&&!Number.isInteger(numeric))throw new Error(`${humanPath(name)} needs a valid ${type}.`);value[name]=numeric;}else value[name]=raw;}$('review-attributes').value=show(value);return value;}
function renderRelationChoices(rows){const select=$('relation-choice'),prior=select.value;select.replaceChildren();const prompt=appendText(select,'option','Choose a record');prompt.value='';for(const record of rows){const id=recordId(record);if(id===selected)continue;const option=appendText(select,'option',`${record.observed_text||record.expression||record.text||'Source record'} · ${record.language||'unknown language'}${record.sense?' · '+record.sense:''}`);option.value=id;}if([...select.options].some(option=>option.value===prior))select.value=prior;}
$('relation-search').addEventListener('input',()=>{clearTimeout(relationTimer);const query=$('relation-search').value;relationTimer=setTimeout(async()=>{try{const params=new URLSearchParams({paged:'1',offset:0,limit:50,query});const result=await api('state?'+params);if(query!==$('relation-search').value)return;renderRelationChoices(result.inventory.records||result.inventory.terms||[]);if(result.inventory.page?.total>50)message('Showing the first 50 related-record matches. Refine your search.');}catch(error){message(error.message,true);}},300);});
$('relation-choice').addEventListener('change',()=>{$('relation-other').value=$('relation-choice').value;});$('relation-other').addEventListener('input',()=>{$('relation-choice').value='';});
function renderPublicationAudit(report){const root=$('publication-audit-result');root.replaceChildren();root.hidden=false;appendText(root,'h3',report.integrity_passed?'Frozen evidence integrity checks passed':'Frozen evidence needs repair');appendText(root,'p',report.requires_researcher_review?'Researcher review remains. Address the findings and report unresolved limitations.':'Read the audit limitations before making research claims.');const dl=document.createElement('dl');dl.className='plan-summary';for(const [key,value]of Object.entries(report.checks||{})){appendText(dl,'dt',humanPath(key));appendText(dl,'dd',String(value));}root.append(dl);for(const issue of report.issues||[])appendText(root,'p',`${issue.severity==='error'?'Repair':'Review'} · ${humanPath(issue.location)}: ${issue.message}`);const list=document.createElement('ul');for(const limitation of report.limitations||[])appendText(list,'li',limitation);root.append(list);const detail=document.createElement('details');appendText(detail,'summary','Full audit record');appendText(detail,'pre',show(report));root.append(detail);}
action('prepare-review',async()=>{const checkedText=$('agent-bundle').value;const review=await api('review',{bundle_text:checkedText,fetch_remote:$('review-fetch-remote').checked});if(checkedText!==$('agent-bundle').value||briefDirty){message('The draft changed during preparation. Check the current draft before approval.',true);return;}if(review.validation){displayValidation(review.validation);return;}editingRecipe=false;await refresh();guidedFingerprint=null;renderGuidedReview(review);message(review.ready?'Source, policy and cost review ready. No extraction models have been called.':review.message||'Resolve the source findings before collection.',!review.ready);},canPrepareReview);
action('approve-start',async()=>{const reviewId=guidedReview.review_id;await api('review/approve',{review_id:reviewId});if(!canRunReviewed()||guidedReview.review_id!==reviewId)throw new Error('The draft or review changed. Inspect the saved approval before starting.');await api('review/run',{review_id:reviewId,max_jobs:number('max-jobs')});await refresh();message('Reviewed collection started. Progress, failures and remaining work are saved.');},()=>canRunReviewed()&&!guidedReview?.approval);
action('resume-reviewed',async()=>{await api('review/run',{review_id:guidedReview.review_id,max_jobs:number('max-jobs')});await refresh();message('Resuming the approved collection with persistent budget and recovery state.');},()=>canRunReviewed()&&Boolean(guidedReview?.approval));
action('release-dataset',async()=>{
  const result=await api('release',{name:$('snapshot-name').value});await refresh();
  $('version-id').value=result.version_id;$('saved-versions').value=result.version_id;
  renderExport(result);renderPublicationAudit(result.audit);renderStudyPacketLinks();
  appendText($('export-result'),'p',result.note||'Choose a new dataset name to save changed records. Reusing this name re-exports its frozen version.');
  if((state.status.jobs?.pending||0)+(state.status.jobs?.partial||0)+(state.status.jobs?.failed||0)+(state.status.jobs?.uncertain||0)>0)appendText($('export-result'),'p','The project inventory has unfinished extraction work. Read the saved version’s coverage and failures in its manifest.','status-note');
  message('Dataset saved, audited and exported locally. No model calls were made.');
},()=>Boolean(state?.recipe)&&!state?.running);
for(const id of ['brief-data-type','brief-mode','brief-profile','brief-policy','brief-question','brief-include','brief-exclude','brief-languages','brief-communities','brief-budget','brief-source-limit','brief-domains','brief-local-roots','brief-date-start','brief-date-end','brief-date-unknown'])$(id).addEventListener('input',()=>{updateDataType();changedBrief();});
$('agent-bundle').addEventListener('input',()=>{hasLocalDraft=true;invalidateBundle();});
$('agent-bundle-file').addEventListener('change',async()=>{try{const file=$('agent-bundle-file').files[0];if(!file)return;if(file.size>512*1024)throw new Error('Use a JSON plan smaller than 512 KiB. Split larger corpora into separate studies.');$('agent-bundle').value=await file.text();hasLocalDraft=true;invalidateBundle();message('Plan file opened. Check the plan before applying it.');}catch(error){message(error.message,true);}finally{$('agent-bundle-file').value='';}});
action('prepare-agent',async()=>{const brief=readBrief(),submitted=show(brief);const setup=await api('agent-setup/prepare',{brief});if(show(readBrief())!==submitted){briefDirty=true;updateSetupButtons();message('Your brief changed while its request was being saved. Create a new request for your current inputs.',true);return;}displayPreparedSetup(setup);message('Brief saved. Ask your Quarry-equipped coding agent to prepare the plan, or expand the chat-agent fallback.');},()=>!state?.running);
action('copy-agent-prompt',()=>copyText('agent-prompt'));
action('download-agent-prompt',async()=>downloadText('v6-agent-request.md',$('agent-prompt').value));
action('download-starter-bundle',async()=>{if(!agentSetup?.starter_bundle)throw new Error('Create a request first.');downloadText('v6-agent-bundle-template.json',show(agentSetup.starter_bundle),'application/json;charset=utf-8');});
action('copy-agent-repair',()=>copyText('agent-repair-prompt'));
action('validate-agent-bundle',async()=>{const checkedText=$('agent-bundle').value;const report=await api('agent-setup/validate',{bundle_text:checkedText});if(checkedText!==$('agent-bundle').value||briefDirty)return;displayValidation(report);if(report.valid){validatedBundleText=checkedText;hasLocalDraft=false;previewPlan(report,JSON.parse(checkedText));message('Plan checks passed. Review the source list, collection policy and cost before applying.');}else{validatedBundleText=null;$('agent-plan-preview').hidden=true;message('The plan needs corrections. Your project is unchanged.',true);}updateSetupButtons();},canValidate);
action('apply-agent-bundle',async()=>{const appliedText=$('agent-bundle').value;const result=await api('agent-setup/apply',{bundle_text:appliedText});if(result.valid===false){displayValidation(result);validatedBundleText=null;updateSetupButtons();return;}appliedBundleText=appliedText;agentSetup={...agentSetup,bundle:JSON.parse(appliedText),applied:true,validation:result,input_files:result.input_files};editingRecipe=false;await refresh();renderEstimate(result.estimate||result.summary?.estimate||{});const count=result.source_ids?.length||0;$('agent-apply-status').textContent=`Plan saved. ${count} local sources imported. Collection has not started.`;const hasRemote=(result.summary?.remote_sources??JSON.parse(appliedText).sources?.filter(s=>s.kind==='url').length)>0;$('fetch-agent-sources').hidden=!hasRemote;$('freeze-agent-corpus').hidden=false;renderInputFiles(result.input_files);updateSetupButtons();message('Plan applied. Inspect sources and the cost estimate before collection.');},canApply);
action('fetch-agent-sources',async()=>{const result=await api('agent-setup/ingest',{});await refresh();$('agent-apply-status').textContent=`Reviewed website fetch complete. ${result.source_ids?.length||0} source IDs returned. Inspect processing failures and source dates before collection.`;message('Reviewed website sources fetched within the saved scope. Model collection has not started.');},canFetch);
action('freeze-agent-corpus',async()=>{const result=await api('agent-setup/freeze',{});await refresh();const root=$('agent-corpus-frozen');root.replaceChildren();root.hidden=false;appendText(root,'h3','Complete-source review packets prepared');appendText(root,'p',`${result.source_count} sources frozen. Blank annotation packets and grouping information are saved in ${result.out}.`);appendText(root,'p','Have humans annotate complete held-out sources before inspecting extracted candidates. Small corpora can have empty held-out splits; inspect the saved split and adjust the study before reporting recall.');appendText(root,'p',result.note||'Quarry does not generate human gold labels. Use an external annotation workflow.');const detail=document.createElement('details');appendText(detail,'summary','Source families, split assignments and packet files');appendText(detail,'pre',show({version_id:result.version_id,split_manifest:result.split_manifest,family_map:result.family_map,annotation_files:result.annotation_files}));root.append(detail);$('version-id').value=result.version_id;$('saved-versions').value=result.version_id;message('Sources frozen for independent human review. Collection has not started.');},canFreeze);
$('recipe').addEventListener('input',()=>editingRecipe=true);$('mode').addEventListener('change',()=>{editingRecipe=true;});$('profile').addEventListener('change',()=>{editingRecipe=true;});$('term-search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{pageOffset=0;refresh().catch(e=>message(e.message,true));},300);});
for(const id of ['review-note','review-attributes'])$(id).addEventListener('input',()=>{editingAnnotation=true;if(id==='review-attributes')editingRawAttributes=true;});
