$('saved-versions').addEventListener('change',()=>{$('version-id').value=$('saved-versions').value;});
action('load-starter',async()=>{if(!starters)starters=await api('starters');$('recipe').value=show(starters[$('starter').value]);editingRecipe=true;message('Starter loaded into editor. Customize it, then validate and save.');});
action('save-recipe',async()=>{await api('configure',{recipe_text:$('recipe').value,mode:$('mode').value,profile:$('profile').value});editingRecipe=false;await refresh();message('Recipe validated and saved. Show a new estimate before collection.');});
action('ingest',async()=>{const result=await api('ingest',{paths:lines('paths'),urls:lines('urls'),metadata_text:$('source-metadata').value});await refresh();message(`Ingested ${result.source_ids.length} sources. Inspect progress for any failures.`);});
action('estimate',async()=>{if(!state?.recipe)throw new Error('Apply your study plan or save a recipe before estimating.');if(editingRecipe)throw new Error('Validate and save the edited recipe before estimating.');renderEstimate(await api('estimate',{links:number('links'),average_chars:number('average-chars'),cache_hit_rate:number('cache-hit-rate')}));message('Cost estimate shown. Its assumptions and coverage are explicit.');});
action('collect',async()=>{if(!state?.recipe)throw new Error('Apply your study plan before collecting.');if(editingRecipe)throw new Error('Validate and save the edited recipe before collection.');renderEstimate(await api('estimate',{}));await api('collect',{max_jobs:number('max-jobs')});await refresh();message('Collection started. Remaining work and failures are persistent.');},()=>Boolean(state?.recipe)&&!state?.running);
action('cancel',async()=>{await api('cancel',{});await refresh();message('Cancellation requested. Resume processes remaining work.');});action('refresh',async()=>{await refresh();state.review=await api('review');if(!briefDirty||!$('brief-question').value.trim())await loadAgentSetup();guidedFingerprint=null;renderGuidedReview(state.review||{});});
action('annotate',async()=>{const termId=selected;const result=await api('annotate',{term_id:termId,status:$('review-status').value,note:$('review-note').value,attributes:readHumanAttributes()});if(selected===termId)editingAnnotation=false;await refresh();message(`Annotation saved: ${result.annotation_id}. Grounded inventory remains complete.`);});
