action('snapshot',async()=>{const result=await api('snapshot',{name:$('snapshot-name').value});await refresh();$('version-id').value=result.version_id;$('saved-versions').value=result.version_id;renderSavedVersion(result,$('snapshot-name').value);message('Frozen dataset version saved.');});
