action('publication-audit',async()=>{const version=$('version-id').value;if(!version)throw new Error('Save or select a dataset version before checking its evidence.');const report=await api('publication-audit',{version});const root=$('publication-audit-result');root.replaceChildren();root.hidden=false;appendText(root,'h3',report.integrity_passed?'Frozen evidence integrity checks passed':'Frozen evidence needs repair');appendText(root,'p',report.requires_researcher_review?'Researcher review remains. Address the items below and report unresolved limitations.':'Read the audit limitations before making research claims.');const dl=document.createElement('dl');dl.className='plan-summary';for(const [key,value]of Object.entries(report.checks||{})){appendText(dl,'dt',humanPath(key));appendText(dl,'dd',String(value));}root.append(dl);for(const issue of report.issues||[])appendText(root,'p',`${issue.severity==='error'?'Repair':'Review'} · ${humanPath(issue.location)}: ${issue.message}`);const list=document.createElement('ul');for(const limitation of report.limitations||[])appendText(list,'li',limitation);root.append(list);const detail=document.createElement('details');appendText(detail,'summary','Full audit record');appendText(detail,'pre',show(report));root.append(detail);message('Saved-version evidence audit complete. Its limits and remaining review work are listed.');});
